#include <iostream>
#include <string>

int main() {
    std::string satz = "Ich lerne C++ mit Freude";

    std::cout << "Satz: " << satz << std::endl;

    std::size_t pos_cpp = satz.find("C++");
    if (pos_cpp != std::string::npos) {
        std::cout << "C++ steht an Position " << pos_cpp << std::endl;
    }

    std::size_t pos_java = satz.find("Java");
    if (pos_java == std::string::npos) {
        std::cout << "Java kommt in dem Satz nicht vor." << std::endl;
    }
    return 0;
}

