#include <iostream>
#include <string>

int main() {
    std::string name = "Ada Lovelace";

    std::size_t leerzeichen = name.find(" ");
    std::string vorname = name.substr(0, leerzeichen);
    std::string nachname = name.substr(leerzeichen + 1);

    std::cout << "Vorname: " << vorname << std::endl;
    std::cout << "Nachname: " << nachname << std::endl;
    std::cout << "Der Vorname hat " << vorname.length() << " Zeichen." << std::endl;
    return 0;
}

#include <iostream>
#include <string>

int main() {
    std::string name = "Ada Lovelace";
    std::size_t leerzeichen = name.find(" ");

    std::string initialen;
    initialen += name[0];
    initialen += ".";
    initialen += name[leerzeichen + 1];
    initialen += ".";

    std::cout << name << " ergibt die Initialen " << initialen << std::endl;
    return 0;
}
